"""Read-only raw gap evidence for a user-confirmed visual case; no classifier."""
import json,hashlib
from pathlib import Path
from decimal import Decimal as D
p=Path('real-review/input/comparison-data.json');raw=p.read_bytes();sha=hashlib.sha256(raw).hexdigest();assert sha=='184bdef0b687ec0ab7bfcaaac2157ff7916fbc1000ef312d81b5efc0c2e73e15';data=json.loads(raw);bars=data['bars'];i=next(i for i,b in enumerate(bars) if b['date']=='2025-04-07');prev,A=bars[i-1],bars[i]
assert prev['date']=='2025-04-02';assert D(A['high'])<D(prev['low'])
gap=D(prev['low'])-D(A['high']);opening=D(A['open'])-D(prev['close']);closechange=D(A['close'])-D(prev['close']);assert gap==D('1.45') and opening==D('-3.20') and closechange==D('-2.60')
B=next(b for b in bars if b['date']=='2025-04-10');C=next(b for b in bars if b['date']=='2025-04-22');priorB=bars[next(i for i,b in enumerate(bars) if b['date']=='2025-04-10')-1];assert D(A['close'])>D(A['open']) and closechange<0;assert D(B['close'])<D(B['open']) and D(B['close'])>D(priorB['close'])
old=data['manual_case_audit']['previous_manual_box'];r=[b for b in bars if old['start']<=b['date']<=old['end']];assert len(r)==39 and all(b in r for b in [A,B,C])
q=Path('whole-membership-review/input/source-query.json');qs=hashlib.sha256(q.read_bytes()).hexdigest();assert qs=='4a43a8c0f03bbffacb86306f064b7c807a7a83bdaf7e737bc76cd654a2c1dbb0'
e={'schema':'m1-confirmed-case-gap-evidence/1','source_comparison_sha256':sha,'source_query_sha256':qs,'core_result_id':data['core']['result_id'],'previous_saved_bar':prev,'A':A,'B':B,'previous_saved_B':priorB,'C':C,'exact_gap_evidence':{'A_high_below_previous_saved_low':True,'previous_low_minus_A_high':str(gap),'A_open_minus_previous_close':str(opening),'A_close_minus_previous_close':str(closechange),'qualification':'RAW_SAVED_ADJACENT_RECORDS_ONLY_NOT_FULL_CALENDAR_OR_CORPORATE_ACTION_CERTIFICATION'},'colour_counterexamples':{'A':'RED_BODY_BUT_BELOW_PREVIOUS_SAVED_CLOSE','B':'GREEN_BODY_BUT_ABOVE_PREVIOUS_SAVED_CLOSE'},'existing_39_record_case':{'start':old['start'],'end':old['end'],'records':len(r),'all_ABC_markers_inside':True,'scope':'Existing already-confirmed interval remains unchanged; this reply does not newly redefine its endpoints or equate original B44/B80 with it.'},'original_core_and_query_unchanged':True,'primary_pressure_id':None,'historical_selection_time':None,'historical_signal_eligible':False}
out=Path('april-decision-review');(out/'evidence.json').write_text(json.dumps(e,ensure_ascii=False,indent=2)+'\n');assert hashlib.sha256(p.read_bytes()).hexdigest()==sha
(out/'verification.json').write_text(json.dumps({'original_hashes_unchanged':True,'adjacent_saved_records_and_gap_decimal_checked':True,'ABC_original_OHLCV_checked':True,'red_green_vs_previous_close_checked':True,'existing_39_record_case_preserved_and_ABC_inside':True,'case_label_not_automatic_classifier':True,'new_product_tests':'NOT_RUN','engine_query_reaction_MACD_bootstrap':'NOT_RUN','new_chart_PDF_browser_ZIP':'NOT_RUN','Android':'NOT_TESTED_NEW_BUILD'},ensure_ascii=False,indent=2)+'\n');print(json.dumps(e['exact_gap_evidence']))
